     1	package hotel;
     2	
     3	import hotel.messages.ArchiveCopy;
     4	import hotel.messages.BlockInvalidAddress;
     5	import hotel.messages.EmailSender;
     6	import hotel.messages.MessageSender;
     7	import hotel.messages.RedirectToTestInbox;
     8	import hotel.messages.SentMessages;
     9	import hotel.reports.OccupancyReport;
    10	import hotel.reports.RevenueReport;
    11	import hotel.reservations.PriceCalculator;
    12	import hotel.reservations.ReservationService;
    13	import hotel.reservations.ReservationStore;
    14	import hotel.rooms.Rooms;
    15	import hotel.web.HttpApi;
    16	import io.javalin.Javalin;
    17	import javax.sql.DataSource;
    18	
    19	/** Puts the inn's pieces together and runs the HTTP server. */
    20	public final class Hotel {
    21	
    22	    private final Javalin server;
    23	
    24	    public Hotel(DataSource dataSource) {
    25	        Rooms rooms = new Rooms(dataSource);
    26	        ReservationStore store = new ReservationStore(dataSource);
    27	        SentMessages sentMessages = new SentMessages(dataSource);
    28	        ReservationService reservations =
    29	                new ReservationService(rooms, store, new PriceCalculator(), messageSender(sentMessages));
    30	        HttpApi api = new HttpApi(
    31	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    32	        this.server = api.server();
    33	    }
    34	
    35	    /**
    36	     * The rules every message goes through. Outside test mode: block invalid addresses, then send and archive a
    37	     * copy. In test mode (HOTEL_TEST_MODE=true): block invalid addresses, then send to the test inbox.
    38	     */
    39	    private static MessageSender messageSender(SentMessages sentMessages) {
    40	        MessageSender email = new EmailSender(sentMessages);
    41	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    42	        MessageSender delivery = testMode ? new RedirectToTestInbox(email) : new ArchiveCopy(email);
    43	        return new BlockInvalidAddress(delivery, sentMessages);
    44	    }
    45	
    46	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    47	    public int start(int port) {
    48	        server.start(port);
    49	        return server.port();
    50	    }
    51	
    52	    public void stop() {
    53	        server.stop();
    54	    }
    55	
    56	    public static void main(String[] args) {
    57	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    58	        Database database = new Database(System.getenv());
    59	        new Hotel(database.dataSource()).start(port);
    60	    }
    61	}
