=== src/main/java/hotel/messages/BlockInvalidAddress.java
     1	package hotel.messages;
     2	
     3	import java.util.regex.Pattern;
     4	
     5	/** A message to an address that cannot be right is not sent: it is listed as BLOCKED. */
     6	public final class BlockInvalidAddress implements MessageSender {
     7	
     8	    /** A single @, something before it, and after it a name with at least one dot in the middle. */
     9	    private static final Pattern VALID_ADDRESS = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
    10	
    11	    private final MessageSender next;
    12	    private final SentMessages sentMessages;
    13	
    14	    public BlockInvalidAddress(MessageSender next, SentMessages sentMessages) {
    15	        this.next = next;
    16	        this.sentMessages = sentMessages;
    17	    }
    18	
    19	    @Override
    20	    public Message send(String to, String subject, String body) {
    21	        if (!VALID_ADDRESS.matcher(to).matches()) {
    22	            return sentMessages.add("EMAIL", to, subject, body, MessageStatus.BLOCKED);
    23	        }
    24	        return next.send(to, subject, body);
    25	    }
    26	}
