=== src/main/java/hotel/messages/SentMessages.java
     1	package hotel.messages;
     2	
     3	import java.sql.Connection;
     4	import java.sql.PreparedStatement;
     5	import java.sql.ResultSet;
     6	import java.sql.SQLException;
     7	import java.util.ArrayList;
     8	import java.util.List;
     9	import javax.sql.DataSource;
    10	
    11	/** Every message the inn sent, so the front desk can check what each guest received. */
    12	public final class SentMessages {
    13	
    14	    private final DataSource dataSource;
    15	
    16	    public SentMessages(DataSource dataSource) {
    17	        this.dataSource = dataSource;
    18	    }
    19	
    20	    Message add(String channel, String to, String subject, String body, MessageStatus status) {
    21	        try (Connection connection = dataSource.getConnection();
    22	                PreparedStatement insert = connection.prepareStatement(
    23	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) "
    24	                                + "RETURNING id")) {
    25	            insert.setString(1, channel);
    26	            insert.setString(2, to);
    27	            insert.setString(3, subject);
    28	            insert.setString(4, body);
    29	            insert.setString(5, status.name());
    30	            try (ResultSet generated = insert.executeQuery()) {
    31	                generated.next();
    32	                return new Message(generated.getLong("id"), channel, to, subject, body, status);
    33	            }
    34	        } catch (SQLException failure) {
    35	            throw new IllegalStateException("could not keep the message to " + to, failure);
    36	        }
    37	    }
    38	
    39	    public List<Message> all() {
    40	        try (Connection connection = dataSource.getConnection();
    41	                PreparedStatement select = connection.prepareStatement(
    42	                        "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    43	                ResultSet rows = select.executeQuery()) {
    44	            List<Message> messages = new ArrayList<>();
    45	            while (rows.next()) {
    46	                messages.add(new Message(
    47	                        rows.getLong("id"),
    48	                        rows.getString("channel"),
    49	                        rows.getString("recipient"),
    50	                        rows.getString("subject"),
    51	                        rows.getString("body"),
    52	                        MessageStatus.valueOf(rows.getString("status"))));
    53	            }
    54	            return messages;
    55	        } catch (SQLException failure) {
    56	            throw new IllegalStateException("could not read the sent messages", failure);
    57	        }
    58	    }
    59	}

