     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.time.LocalDate;
     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	
    12	/** Which rooms are occupied on a given night, for the front desk (CSV). */
    13	public final class OccupancyReport {
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	
    18	    public OccupancyReport(Rooms rooms, ReservationStore store) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	    }
    22	
    23	    public String generate(LocalDate night) {
    24	        List<Reservation> occupying = new ArrayList<>();
    25	        for (Reservation reservation : store.all()) {
    26	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    27	            if (reservation.isPaid() && coversNight) {
    28	                occupying.add(reservation);
    29	            }
    30	        }
    31	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
    32	
    33	        StringBuilder csv = new StringBuilder();
    34	        csv.append("room,type,reservation,check_in,check_out\n");
    35	        for (Reservation reservation : occupying) {
    36	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    37	            csv.append(room.number()).append(',')
    38	                    .append(room.type()).append(',')
    39	                    .append(reservation.id()).append(',')
    40	                    .append(reservation.checkIn()).append(',')
    41	                    .append(reservation.checkOut()).append('\n');
    42	        }
    43	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
    44	        return csv.toString();
    45	    }
    46	}
