 96	class ReservationServiceTest {
 97	
 98	    private final EmptyDatabase database = new EmptyDatabase();
 99	    private final SentMessages sentMessages = new SentMessages(database.dataSource());
100	    private final ReservationService service = new ReservationService(
101	            new Rooms(database.dataSource()), new ReservationStore(database.dataSource()), new PriceCalculator(),
102	            new EmailSender(sentMessages));
103	
104	    @AfterEach
105	    void closeDatabase() {
106	        database.close();
107	    }
108	
109	    private static NewReservation stay(int roomNumber, String checkIn, String checkOut, int guests, RatePlan plan) {
110	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
111	        return new NewReservation(
112	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
113	    }
114	
115	    private static ErrorCode errorOf(Runnable action) {
116	        return assertThrows(HotelException.class, action::run).errorCode();
117	    }
118	
119	    @Test
120	    void aNewReservationIsPendingWithItsPrice() {
121	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
122	
123	        assertEquals(ReservationStatus.PENDING, reservation.status());
124	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
125	        assertNull(reservation.refund());
126	    }
127	
128	    @Test
129	    void refusesInvalidStays() {
130	        assertEquals(ErrorCode.INVALID_REQUEST,
131	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
132	        assertEquals(ErrorCode.INVALID_REQUEST,
133	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
134	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
135	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
136	        assertEquals(ErrorCode.CAPACITY_EXCEEDED,
137	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD))));
138	    }
139	
140	    @Test
141	    void aRoomCannotBeBookedTwiceForTheSameNight() {
142	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
143	
144	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
145	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
146	        // the check-out day is free for the next guest, and another room is free on the same nights
147	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
148	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
149	    }
150	
151	    @Test
152	    void aCancelledReservationFreesTheRoom() {
153	        Reservation first = service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
154	        service.cancel(first.id());
155	
